    const botonMovil = ([view, label2, ico]) => `<button class="${esActivo(view) ? "active" : ""}" data-view="${view}"${esActivo(view) ? ' aria-current="page"' : ""}><span class="ico" aria-hidden="true">${icono(ico)}</span><span>${label2}</span></button>`;
    const extraIsActive = mobileExtra.some(([view]) => esActivo(view));
